<style>
.tarifas{display:grid;gap:18px}.tarifas .panel{background:var(--surface-color,#fff);border:1px solid var(--surface-border,#e2e8f0);border-radius:12px;padding:20px}.tarifas h1{font-size:1.45rem;margin:0}.tarifas h2{font-size:1rem;margin:0 0 12px}.tarifas .muted{color:var(--text-muted,#64748b);font-size:.8rem}.tarifas .toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.tarifas .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.tarifas .stat{border-top:3px solid #2563eb}.tarifas .stat strong{display:block;font-size:1.6rem;margin-top:5px}.tarifas .filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.tarifas label{display:block;font-size:.75rem;font-weight:600;margin-bottom:5px}.tarifas input,.tarifas select,.tarifas textarea{width:100%;background:var(--surface-color,#fff);color:var(--text-primary,#172033);border:1px solid var(--surface-border,#cbd5e1);border-radius:6px;padding:9px;font:inherit;font-size:.8rem}.tarifas .table-wrap{overflow:auto;max-height:620px}.tarifas table{width:100%;border-collapse:collapse;font-size:.76rem}.tarifas th{position:sticky;top:0;background:var(--surface-color,#f8fafc);text-align:left;white-space:nowrap;color:var(--text-muted,#64748b);font-size:.67rem;text-transform:uppercase;z-index:1}.tarifas th,.tarifas td{padding:10px 12px;border-bottom:1px solid var(--surface-border,#e2e8f0)}.tarifas td{vertical-align:top}.tarifas .number{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.tarifas .badge{display:inline-block;border-radius:5px;padding:3px 6px;font-size:.68rem;font-weight:600}.tarifas .pendiente{color:#92400e;background:#fef3c7}.tarifas .confirmada{color:#166534;background:#dcfce7}.tarifas .descartada{color:#475569;background:#e2e8f0}.tarifas .note{border-left:3px solid #f59e0b;padding:12px;background:var(--surface-color,#fff);font-size:.83rem}.tarifas summary{cursor:pointer;font-weight:600;font-size:.86rem}.tarifas .empty{text-align:center;padding:40px;color:var(--text-muted,#64748b)}.tarifas .actions{display:flex;gap:8px;flex-wrap:wrap}.tarifas .split{display:grid;grid-template-columns:2fr 1fr;gap:18px}.tarifas pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.72rem}.tarifas .error{color:#b91c1c}@media(max-width:950px){.tarifas .filters,.tarifas .stats{grid-template-columns:repeat(2,minmax(0,1fr))}.tarifas .split{grid-template-columns:1fr}}@media(max-width:520px){.tarifas .filters{grid-template-columns:1fr}}
</style>
